<?php require 'includes/db.php';$title='Service Tickets';
if(isset($_GET['delete'])){$s=$conn->prepare("DELETE FROM tickets WHERE id=?");$s->bind_param('i',$_GET['delete']);$s->execute();header('Location: tickets.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$conn->prepare("INSERT INTO tickets(ticket_number,employee_id,asset_id,title,description,priority,status) VALUES(?,?,?,?,?,?,?)");$e=$_POST['employee_id']===''?null:(int)$_POST['employee_id'];$a=$_POST['asset_id']===''?null:(int)$_POST['asset_id'];$s->bind_param('siissss',$_POST['ticket_number'],$e,$a,$_POST['title'],$_POST['description'],$_POST['priority'],$_POST['status']);$s->execute();header('Location: tickets.php');exit;}
$emps=$conn->query("SELECT id,name FROM employees ORDER BY name");$assets=$conn->query("SELECT id,asset_tag FROM assets ORDER BY asset_tag");$rows=$conn->query("SELECT t.*,e.name employee,a.asset_tag FROM tickets t LEFT JOIN employees e ON e.id=t.employee_id LEFT JOIN assets a ON a.id=t.asset_id ORDER BY t.id DESC");require 'includes/header.php';?>
<div class="toolbar"><div><h2>Service Desk</h2><p>Create and track IT support requests.</p></div><button class="btn" onclick="add.showModal()">+ New Ticket</button></div><section class="panel"><table><tr><th>Ticket</th><th>Issue</th><th>Employee</th><th>Asset</th><th>Priority</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($r['ticket_number'])?></b></td><td><?=htmlspecialchars($r['title'])?></td><td><?=htmlspecialchars($r['employee']??'—')?></td><td><?=htmlspecialchars($r['asset_tag']??'—')?></td><td><i class="<?=strtolower($r['priority'])?>"><?=htmlspecialchars($r['priority'])?></i></td><td><em><?=htmlspecialchars($r['status'])?></em></td><td><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete ticket?')">Delete</a></td></tr><?php endwhile;?></table></section>
<dialog id="add"><form method="post"><h3>Create Service Ticket <button type="button" onclick="add.close()">×</button></h3><div class="grid"><label>Ticket Number<input name="ticket_number" value="TKT-<?=date('His')?>" required></label><label>Employee<select name="employee_id"><option value="">Select</option><?php while($e=$emps->fetch_assoc()):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['name'])?></option><?php endwhile;?></select></label><label>Asset<select name="asset_id"><option value="">Select</option><?php while($a=$assets->fetch_assoc()):?><option value="<?=$a['id']?>"><?=htmlspecialchars($a['asset_tag'])?></option><?php endwhile;?></select></label><label>Priority<select name="priority"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></label><label>Title<input name="title" required></label><label>Status<select name="status"><option>Open</option><option>In Progress</option><option>Resolved</option><option>Closed</option></select></label><label class="full">Description<textarea name="description"></textarea></label></div><button class="btn">Create Ticket</button></form></dialog><?php require 'includes/footer.php';?>